try {
  // Get AI output text from previous node
  const aiText = $input.first().json.output;

  if (!aiText) {
    return [{ 
      json: { 
        summary: "", 
        education: "", 
        certifications: "", 
        strengths: [], 
        weaknesses: [], 
        ideal_roles: [], 
        fit_score: 0,
        parsing_error: "No AI output received"
      } 
    }];
  }

  // Initialize output fields
  let summary = "";
  let education = "";
  let certifications = "";
  let strengths = [];
  let weaknesses = [];
  let ideal_roles = [];
  let fit_score = "";

  // Split into lines
  const lines = aiText.split("\n");

  // Track current section
  let currentSection = "summary";

  for (let line of lines) {
    let trimmed = line.trim();
    if (!trimmed) continue;

    // Detect section headers
    if (/^Summary:/i.test(trimmed)) {
      currentSection = "summary";
      // Extract inline content if present
      const inlineContent = trimmed.replace(/^Summary:/i, "").trim();
      if (inlineContent) summary = inlineContent;
      continue;
    }
    if (/^Education:/i.test(trimmed)) {
      currentSection = "education";
      continue;
    }
    if (/^Certifications:/i.test(trimmed)) {
      currentSection = "certifications";
      continue;
    }
    if (/^Strengths:/i.test(trimmed)) {
      currentSection = "strengths";
      continue;
    }
    if (/^Weaknesses:/i.test(trimmed)) {
      currentSection = "weaknesses";
      continue;
    }
    if (/^Ideal Roles:/i.test(trimmed)) {
      currentSection = "ideal_roles";
      continue;
    }
    if (/^Fit Score:/i.test(trimmed)) {
      fit_score = trimmed.replace(/^Fit Score:/i, "").trim();
      continue;
    }

    // Add lines to the correct section
    switch(currentSection) {
      case "summary":
        summary += (summary ? " " : "") + trimmed;
        break;
      case "education":
        education += (education ? " " : "") + trimmed;
        break;
      case "certifications":
        certifications += (certifications ? " " : "") + trimmed;
        break;
      case "strengths":
        const strength = trimmed.replace(/^[-•*]\s*/, "").trim();
        if (strength) strengths.push(strength);
        break;
      case "weaknesses":
        const weakness = trimmed.replace(/^[-•*]\s*/, "").trim();
        if (weakness) weaknesses.push(weakness);
        break;
      case "ideal_roles":
        const role = trimmed.replace(/^[-•*]\s*/, "").trim();
        if (role) ideal_roles.push(role);
        break;
      default:
        break;
    }
  }

  // Convert fit_score to number
  const numericFitScore = Number(fit_score.replace(/\/10/g, "").trim());
  fit_score = isNaN(numericFitScore) ? 0 : numericFitScore;

  // Return structured JSON
  return [{
    json: {
      summary: summary.trim(),
      education: education.trim(),
      certifications: certifications.trim(),
      strengths,
      weaknesses,
      ideal_roles,
      fit_score
    }
  }];

} catch (error) {
  // Return error info instead of crashing
  return [{
    json: {
      summary: "",
      education: "",
      certifications: "",
      strengths: [],
      weaknesses: [],
      ideal_roles: [],
      fit_score: 0,
      parsing_error: error.message
    }
  }];
}

