// Validate incoming webhook payload for Deepsearch
const body = $json.body;
const errors = [];

// Required field: linkedin_url
if (!body.linkedin_url || typeof body.linkedin_url !== 'string' || !body.linkedin_url.trim()) {
  errors.push('linkedin_url is required and must be a non-empty string');
} else if (!body.linkedin_url.includes('linkedin.com')) {
  errors.push('linkedin_url must be a valid LinkedIn URL');
}

// Required field: candidate_id
if (!body.candidate_id || typeof body.candidate_id !== 'string' || !body.candidate_id.trim()) {
  errors.push('candidate_id is required and must be a non-empty string');
}

// Optional but recommended: evaluation_prompt
if (body.evaluation_prompt && typeof body.evaluation_prompt !== 'string') {
  errors.push('evaluation_prompt must be a string if provided');
}

// If validation fails, throw error with details
if (errors.length > 0) {
  throw new Error(JSON.stringify({
    validation_failed: true,
    errors: errors,
    received: {
      linkedin_url: body.linkedin_url ? 'provided' : 'missing',
      candidate_id: body.candidate_id ? 'provided' : 'missing',
      evaluation_prompt: body.evaluation_prompt ? 'provided' : 'missing'
    }
  }));
}

// Validation passed - pass through the original data
return [{ json: $json }];

// Format success response for frontend
const webhookData = $('Webhook').first().json.body;
const apifyData = $('Run an Actor and get dataset1').first().json;
const aiParsedData = $('Code in JavaScript').first().json;
const supabaseResult = $input.first().json;

// Build comprehensive response
return [{
  json: {
    success: true,
    message: 'Candidate analysis completed successfully',
    data: {
      candidate_id: webhookData.candidate_id,
      candidate_name: apifyData?.basic_info?.fullname || webhookData.candidate_name || 'Unknown',
      linkedin_url: apifyData?.basic_info?.profile_url || webhookData.linkedin_url,
      company: apifyData?.basic_info?.current_company || '',
      profile_picture_url: apifyData?.basic_info?.profile_picture_url || '',
      analysis: {
        summary: aiParsedData.summary || '',
        education: aiParsedData.education || '',
        certifications: aiParsedData.certifications || '',
        strengths: aiParsedData.strengths || [],
        weaknesses: aiParsedData.weaknesses || [],
        ideal_roles: aiParsedData.ideal_roles || [],
        fit_score: aiParsedData.fit_score || 0
      },
      database_record_id: supabaseResult.id || null,
      timestamp: new Date().toISOString()
    },
    errors: []
  }
}];

// Aggregate error information from failed nodes
const inputData = $input.first().json;
const webhookData = $('Webhook').first().json.body;

// Determine error stage and details
let stage = 'unknown';
let errorMessage = 'Unknown error occurred';
let details = '';

// Check if this is a validation error
try {
  if (typeof inputData.message === 'string' && inputData.message.includes('validation_failed')) {
    const parsed = JSON.parse(inputData.message);
    stage = 'input_validation';
    errorMessage = 'Invalid input parameters';
    details = JSON.stringify(parsed.errors);
  } else if (inputData.error) {
    errorMessage = inputData.error.message || inputData.error || 'Execution failed';
    details = inputData.error.description || '';

    // Determine stage from error context
    if (errorMessage.toLowerCase().includes('apify') || errorMessage.toLowerCase().includes('linkedin')) {
      stage = 'linkedin_scraping';
    } else if (errorMessage.toLowerCase().includes('anthropic') || errorMessage.toLowerCase().includes('ai') || errorMessage.toLowerCase().includes('claude')) {
      stage = 'ai_analysis';
    } else if (errorMessage.toLowerCase().includes('supabase') || errorMessage.toLowerCase().includes('database')) {
      stage = 'database_insert';
    }
  } else {
    errorMessage = inputData.message || JSON.stringify(inputData);
  }
} catch (e) {
  errorMessage = inputData.message || 'Error processing failed';
}

return [{
  json: {
    success: false,
    message: 'Failed to complete candidate analysis',
    data: {
      candidate_id: webhookData?.candidate_id || null,
      linkedin_url: webhookData?.linkedin_url || null
    },
    errors: [{
      stage: stage,
      error: errorMessage,
      details: details
    }]
  }
}];
